class Solution {
    public boolean hasCycle(ListNode head) {
        if(head == null || head.next==null) return false;
        ListNode tortoise = head;
        ListNode hare = head;

        while(hare!=null){
            hare = hare.next;
            tortoise = tortoise.next;
            if(hare!=null){
                hare = hare.next;
            }
            if(hare == tortoise) return true;
        }
        return false;
    }
}
